<main class="page-shell success-page"><div class="success-mark"><?= $registration['status']==='confirmed'?'✓':'…' ?></div><span class="eyebrow accent">REGISTRATION / <?= $registration['status']==='confirmed'?'CONFIRMED':'CREATED' ?></span><h1><?= $registration['status']==='confirmed'?'You’re':'Almost' ?><br><em><?= $registration['status']==='confirmed'?'in.':'there.' ?></em></h1><p class="success-lede"><?= $registration['status']==='confirmed'?'Your registration and secure event pass are active.':'Your place is held while payment is completed.' ?> Keep this registration ID safe.</p><div class="confirmation-card" data-testid="registration-confirmation-card"><div><span class="eyebrow">REGISTRATION ID</span><strong class="mono registration-code" data-testid="registration-id"><?= esc($registration['registration_id']) ?></strong></div><div><span class="eyebrow">PARTICIPANT</span><strong data-testid="confirmation-participant"><?= esc($registration['participant_name']) ?></strong></div><div><span class="eyebrow">EVENT</span><strong data-testid="confirmation-event"><?= esc($registration['event_name']) ?></strong></div><div class="confirmation-amount"><span class="eyebrow">SERVER-VERIFIED AMOUNT</span><strong data-testid="confirmation-server-amount"><?= esc(money($registration['total_amount'])) ?></strong></div><div><span class="eyebrow">PAYMENT / REGISTRATION</span><span class="status status-<?= $registration['status']==='confirmed'?'success':'warning' ?>" data-testid="confirmation-status"><?= esc(strtoupper(str_replace('_',' ',$registration['status']))) ?></span></div><div><span class="eyebrow">VENUE</span><strong><?= esc($registration['venue']?:'SAGE University Indore') ?></strong></div><div class="confirmation-actions"><?php if($registration['status']==='confirmed'&&$passAccess): ?><a class="button button-yellow" href="<?= base_url('pass/'.$registration['registration_id']).'?key='.rawurlencode($passAccess) ?>" data-testid="view-pass-button">View digital pass <span>↗</span></a><a class="button button-ghost" href="<?= base_url('pass/'.$registration['registration_id'].'/download').'?key='.rawurlencode($passAccess) ?>" data-testid="download-pass-button">Download PDF pass</a><?php elseif($registration['status']==='pending_payment'): ?><a class="button button-yellow" target="_blank" rel="noopener" href="<?= base_url('payment/'.$registration['registration_id']) ?>" data-testid="complete-payment-button">Complete payment <span>↗</span></a><span class="notice-warning">Your pass unlocks only after server-side Easebuzz verification.</span><?php endif ?><a class="button button-ghost" href="<?= base_url('events') ?>" data-testid="confirmation-events-link">Back to events</a></div></div></main>